export function wallesterPublicKeyText(value){const text=String(value||'').trim();if(text.startsWith('-----BEGIN PUBLIC KEY-----'))return text;try{const decoded=atob(text);return decoded.startsWith('-----BEGIN PUBLIC KEY-----')?decoded:text;}catch{return text;}}
