async function copyCalendlyText(value){
 const text=String(value||'').trim();
 if(!text)throw new Error('Link Calendly non disponibile.');
 if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);return;}
 const field=document.createElement('textarea');field.value=text;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();
 try{if(!document.execCommand('copy'))throw new Error('Copia non riuscita.');}finally{field.remove();}
}

export async function renderCalendlySection({main,state,api,esc,pageHeader,toast,navigate,calendly,standalone=false}){
 if(!standalone)main.querySelector('.calendly-dedicated-section')?.remove();
 const section=document.createElement('section');section.className='panel calendly-dedicated-section';
 section.innerHTML='<p class="eyebrow">CALENDLY · COLLEGAMENTO ATTIVO</p><h2>Gestione Calendly</h2><p>Profilo, tipi di evento, link di prenotazione, appuntamenti, invitati e disponibilità sono gestiti nella sezione Calendly di PRIME.</p><div class="connect-actions">'+(standalone?'<button type="button" class="secondary" data-calendly-back>← Torna a PRIME Connect</button>':'<button type="button" class="primary" data-calendly-open>Apri sezione Calendly</button>')+'<button type="button" class="secondary" data-calendly-sync>Sincronizza ora</button>'+(standalone?'<button type="button" class="secondary" data-calendly-disconnect>Scollega Calendly</button>':'')+'</div><div class="calendly-dedicated-content"><p class="small-note">Caricamento appuntamenti, tipi di evento e invitati…</p></div>';
 if(standalone){main.innerHTML=pageHeader('CONNESSIONI','Calendly','Gestisci il collegamento Calendly direttamente in PRIME.');main.append(section);}else main.querySelector('.connect-cards')?.after(section);
 const content=section.querySelector('.calendly-dedicated-content');
 try{
  const value=await api('/api/connect/connections/'+calendly.id+'/calendly-overview');
  const types=value.event_types||[],events=value.scheduled_events||[],invitees=value.invitees||[],availability=value.availability||[];
  const typeRows=types.map(t=>{const link=String(t.booking_url||''),isThirty=/30\s*(?:min|minute)/i.test(t.name||''),copyLabel=isThirty?'Copia link 30 minuti':'Copia link';return '<p><strong>'+esc(t.name)+'</strong> · '+(link?'<a href="'+esc(link)+'" target="_blank" rel="noopener noreferrer">Apri link ↗</a> <button type="button" class="text-button" data-calendly-copy="'+esc(link)+'" data-copy-label="'+copyLabel+'">'+copyLabel+'</button>':'<span class="muted">Link non disponibile</span>')+'</p>';}).join('');
  content.innerHTML='<div class="calendly-overview-grid"><article><h3>Profilo</h3><p>'+esc(value.user?.name||calendly.account_label||'Account Calendly')+'</p><p class="small-note">'+esc(value.user?.scheduling_url||'')+'</p></article><article><h3>Tipi di evento</h3>'+(typeRows||'<p>Nessun tipo di evento restituito.</p>')+'</article><article><h3>Disponibilità</h3><p>'+availability.length+' configurazioni restituite.</p></article></div><h3>Appuntamenti recenti</h3><div class="calendly-event-list">'+(events.slice(0,50).map(e=>'<article class="calendly-event"><strong>'+esc(e.name||'Appuntamento')+'</strong> <span class="pill">'+esc(e.status||'scheduled')+'</span><p>'+esc(e.start_time||'')+' · '+esc(e.location?.join_url||e.location?.type||'')+'</p><button type="button" class="secondary" data-calendly-cancel="'+esc(e.uri||'')+'">Annulla evento</button></article>').join('')||'<p>Nessun appuntamento recente.</p>')+'</div><h3>Invitati</h3><div>'+(invitees.slice(0,100).map(item=>'<p><strong>'+esc(item.name||item.email||'Invitato')+'</strong> · '+esc(item.status||'')+' · '+esc(item.email||'')+'</p>').join('')||'<p>Nessun invitato recente.</p>')+'</div>';
  section.querySelectorAll('[data-calendly-copy]').forEach(button=>button.onclick=async()=>{try{await copyCalendlyText(button.dataset.calendlyCopy);button.textContent='Copiato';toast('Link Calendly copiato negli appunti.');setTimeout(()=>{button.textContent=button.dataset.copyLabel||'Copia link';},1800);}catch(error){toast(error.message);}});
  section.querySelectorAll('[data-calendly-cancel]').forEach(button=>button.onclick=async()=>{try{button.disabled=true;await api('/api/connect/connections/'+calendly.id+'/calendly-cancel',{method:'POST',body:JSON.stringify({event_id:button.dataset.calendlyCancel})});toast('Evento Calendly annullato.');await renderCalendlySection({main,state,api,esc,pageHeader,toast,navigate,calendly,standalone});}catch(error){button.disabled=false;toast(error.message);}});
 }catch(error){content.innerHTML='<p class="error">'+esc(error.message)+'</p>';}
 section.querySelector('[data-calendly-open]')?.addEventListener('click',()=>navigate?.('calendly'));
 section.querySelector('[data-calendly-back]')?.addEventListener('click',()=>navigate?.('connect'));
 section.querySelector('[data-calendly-disconnect]')?.addEventListener('click',async()=>{try{const result=await api('/api/connect/connections/'+calendly.id,{method:'DELETE',body:'{}'});state.calendlyConnected=false;toast(result.calendly_access_revoked?'Accesso Calendly revocato.':'Calendly scollegato.');await navigate?.('connect');}catch(error){toast(error.message);}});
 section.querySelector('[data-calendly-sync]')?.addEventListener('click',async()=>{try{await api('/api/connect/connections/'+calendly.id+'/sync',{method:'POST',body:'{}'});toast('Calendly sincronizzato.');await renderCalendlySection({main,state,api,esc,pageHeader,toast,navigate,calendly,standalone});}catch(error){toast(error.message);}});
 return section;
}
