 const run=async(card,fn)=>{const feedback=card.querySelector('.connect-feedback')||card.querySelector('[role=status]');card.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(feedback)feedback.textContent='Operazione in corso…';await fn();}catch(error){if(feedback)feedback.textContent=error.message;toast(error.message);}finally{card.querySelectorAll('button').forEach(b=>b.disabled=false);}};
 const refresh=()=>renderConnect({main,state,api,esc,pageHeader,toast,navigate});
 let wallesterState=wallester,wallesterTransactions=[],wallesterTotal=0;
