 const money=(amount,currency)=>{if(!Number.isFinite(amount))return '—';const code=/^[A-Z]{3}$/.test(currency||'')?currency:'EUR';return new Intl.NumberFormat(english?'en-GB':'it-IT',{style:'currency',currency:code}).format(amount);};
